class Solution {
public:
    vector<int> getMaximumXor(vector<int>& nums, int maximumBit) {
        int maxMask = (1 << maximumBit) - 1;
        int x = 0;
        for (int num : nums) x ^= num;

        int n = nums.size();
        vector<int> ans;
        ans.reserve(n);
        for (int i = n - 1; i >= 0; --i) {
            ans.push_back(x ^ maxMask);
            x ^= nums[i];
        }
        return ans;
    }
};

class Solution {
    public int[] getMaximumXor(int[] nums, int maximumBit) {
        int maxMask = (1 << maximumBit) - 1;
        int x = 0;
        for (int num : nums) x ^= num;

        int n = nums.length;
        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            ans[i] = x ^ maxMask;
            x ^= nums[n - 1 - i];
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} maximumBit
 * @return {number[]}
 */
var getMaximumXor = function(nums, maximumBit) {
    const maxMask = (1 << maximumBit) - 1;
    let x = 0;
    for (const num of nums) x ^= num;

    const n = nums.length;
    const ans = [];
    for (let i = n - 1; i >= 0; --i) {
        ans.push(x ^ maxMask);
        x ^= nums[i];
    }
    return ans;
};
